  FROM (SELECT string_agg(c.id || ': want ' || coalesce(c.want, '(null)') || ', got ' || coalesce(c.got, '(null)'), ' | ' ORDER BY c.id COLLATE "C") AS msg
          FROM checks c WHERE c.got IS DISTINCT FROM c.want) f;
